import {getAction} from '@madou/catalog';
import {createGame,gameStats,transition,allCardInstanceIds,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand} from './scenario-tools.js';
export const bloodFlowCard='a2-p09-r2c3';
export const bloodFlowScenarios=['blood-flow-ordinary','blood-flow-owner-ordinary','blood-flow-low','blood-flow-dedicated','blood-flow-pair','blood-flow-all','blood-flow-near','blood-flow-same-faction','blood-flow-water-ordinary','blood-flow-water','blood-flow-water-equal','blood-flow-maai-ordinary','blood-flow-maai-dedicated','blood-flow-evade-ordinary','blood-flow-evade-dedicated','blood-flow-fate','blood-flow-suppressed','blood-flow-silenced','blood-flow-stopped','blood-flow-wrong-owner','blood-flow-decline','blood-flow-noncounter','blood-flow-good','blood-flow-unprepared-ordinary','blood-flow-unprepared-dedicated','blood-flow-resistance-fail','blood-flow-force-fail','blood-flow-reroll','blood-flow-force-reroll','blood-flow-chant-ordinary','blood-flow-chant-dedicated'] as const;
export type BloodFlowScenario=typeof bloodFlowScenarios[number];
export function isBloodFlowScenario(name:string):name is BloodFlowScenario{return (bloodFlowScenarios as readonly string[]).includes(name);}
export function bloodFlowMode(name:BloodFlowScenario){const suffix=name.replace('blood-flow-',''),dedicated=!['ordinary','owner-ordinary','low','evade-ordinary','water-ordinary','maai-ordinary','decline','good','unprepared-ordinary','chant-ordinary'].includes(suffix),owner=dedicated&&suffix!=='wrong-owner'||suffix==='owner-ordinary',water=suffix.startsWith('water'),targets=suffix==='all'?[1,2,3]:suffix==='same-faction'?[1,3]:['pair','maai-dedicated','suppressed','silenced','resistance-fail'].includes(suffix)?[1,2]:[1];return {suffix,dedicated,owner,water,targets};}
/** Only initial deal/training is arranged. Followers, OPEN, statuses and preparation use accepted commands. */
export function makeBloodFlowPhysical(name:BloodFlowScenario,players:{id:string;name:string}[],options:{beforeStart?:boolean;prepared?:boolean;warrior?:number;spirit?:number;targetSpirit?:number}={}){
 const m=bloodFlowMode(name),prior=['suppressed','stopped','silenced'].includes(m.suffix),incoming=m.suffix==='noncounter';let s=createGame(players,entropy(),{startingSeat:prior?3:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];
 for(const [i,p] of players.entries())assignCharacter(s,p.id,[m.owner?'魔導王ガイナス':m.suffix==='good'?'侍大将のシン':'黒騎士ガーウィン',m.suffix==='good'?'獣使いのウパニシャット':'侍大将のシン','黒妖精のアーネス','聖騎士ランスロット'][i]!);
 for(const p of Object.values(s.players)){p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};p.permanent.spirit!+=(p.id===a?options.spirit??6:p.id===b?options.targetSpirit??6:p.id===c?12:6)-gameStats(s,p.id).spirit;}
 s.players[a]!.permanent!.warrior_level!+=(options.warrior??(m.suffix==='low'?7:m.dedicated?0:8))-gameStats(s,a).warrior_level;
 const keep=[takeCard(s,a,bloodFlowCard),takeCard(s,d,'a2-p02-r2c3')];if(m.water)keep.push(takeCard(s,b,'a2-p23-r1c1'));if(m.suffix==='near')keep.push(takeCard(s,a,'a2-p24-r1c3'));if(m.suffix.startsWith('maai'))keep.push(takeCard(s,b,'a2-p06-r1c3'));if(m.suffix.startsWith('evade'))keep.push(takeCard(s,b,'a2-p05-r3c1'));if(m.suffix.includes('reroll'))keep.push(takeCard(s,c,'a2-p02-r1c3'));if(incoming)keep.push(takeCard(s,b,'a2-p24-r1c2'));if(prior)keep.push(takeCard(s,d,m.suffix==='suppressed'?'a2-p13-r1c2':m.suffix==='stopped'?'a2-p13-r2c1':'a2-p18-r1c1'));
 for(const p of players)trimHand(s,p.id,...keep);s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];if(m.suffix==='water-equal'){takeCard(s,b,'a2-p01-r2c1');s.players[b]!.hand=s.players[b]!.hand.filter(id=>id!=='a2-p01-r2c1');s.deck.unshift('a2-p01-r2c1');}s.events=[];
 function act(actorId:string,command:GameCommand,face=1){const input={actorId,command},e={...entropy(),dice:Array(100).fill(face)},r=transition(s,input,e);if(!r.ok)throw Error(`BLOOD_FLOW_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('BLOOD_FLOW_FIXTURE_REPLAY');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('BLOOD_FLOW_FIXTURE_CARDS');}
 function settle(face=1){for(let n=0;n<600;n++){const w=s.windows?.at(-1);if(!w)return;act(w.participants[w.cursor]!,{type:'PASS'},face);}throw Error('BLOOD_FLOW_FIXTURE_LIMIT');}
 for(const id of [a,b,c,d]){if(m.water&&id===b)act(b,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:'a2-p23-r1c1'});act(id,{type:'PASS_SETUP'});}if(options.beforeStart)return s;
 if(prior){act(d,{type:'START_TURN'});settle();act(d,{type:'CHOOSE_DRAW',draw:false});act(d,{type:'ATTACK',cardInstanceId:m.suffix==='suppressed'?'a2-p13-r1c2':m.suffix==='stopped'?'a2-p13-r2c1':'a2-p18-r1c1',targetIds:[a],dedicated:false});settle(6);if(s.phase==='withdrawal')act(d,{type:'PASS_WITHDRAWAL'});act(d,{type:'END_TURN',discardIds:[]});settle();}
 act(a,{type:'START_TURN'});settle(prior?6:1);if(s.phase==='draw')act(a,{type:'CHOOSE_DRAW',draw:false});if(['good','stopped','decline'].includes(m.suffix)||m.suffix.startsWith('unprepared')||m.suffix.startsWith('chant-')||options.prepared===false)return s;
 act(a,{type:'CHANT',cardInstanceId:bloodFlowCard,dedicated:m.suffix==='wrong-owner'?false:m.dedicated});for(let n=0;n<250;n++){const id=s.seatOrder[s.turnSeat]!,w=s.windows?.at(-1);if(w)act(w.participants[w.cursor]!,{type:'PASS'},prior?6:1);else if(s.phase==='action'){if(id===a)break;if(incoming&&id===b){act(b,{type:'ATTACK',cardInstanceId:'a2-p24-r1c2',targetIds:[a],dedicated:false});for(let k=0;k<300;k++){if(s.windows?.at(-1)?.kind==='normal-defense')return s;const next=s.windows!.at(-1)!;act(next.participants[next.cursor]!,{type:'PASS'});}throw Error('BLOOD_FLOW_INCOMING_LIMIT');}act(id,{type:'PASS_ACTION'});}else if(s.phase==='withdrawal')act(id,{type:'PASS_WITHDRAWAL'});else if(s.phase==='hand-adjustment')act(id,{type:'END_TURN',discardIds:s.players[id]!.hand.slice(gameStats(s,id).handLimit)});else if(s.phase==='turn-start')act(id,{type:'START_TURN'});else if(s.phase==='draw')act(id,{type:'CHOOSE_DRAW',draw:false});else throw Error('BLOOD_FLOW_TURN');}
 if(m.suffix==='near'){act(a,{type:'APPROACH',cardInstanceId:'a2-p24-r1c3',targetId:b});settle();}if(m.suffix==='same-faction'){act(c,{type:'REVEAL_CHARACTER'});settle();}return s;
}
